from pyscipopt import Model
for sense in ["maximize","max","minimize","min"]:
 try:
  m=Model(); x=m.addVar(vtype="B"); m.setObjective(x,sense=sense); m.optimize(); print(sense,"objective_sense",m.getObjectiveSense(),"objective",m.getObjVal(),"x",m.getVal(x),"status",m.getStatus())
 except Exception as exc: print(sense,type(exc).__name__,str(exc))
m=Model(); x=m.addVar(vtype="B"); m.setMaximize(); m.setObjective(x); m.optimize(); print("setMaximize()","objective_sense",m.getObjectiveSense(),"objective",m.getObjVal(),"x",m.getVal(x),"status",m.getStatus())
